export function StoryCard({
  persona = "{{persona}}",
  need = "{{need}}",
  benefit = "{{benefit}}",
  points = {{points}},
  status = "{{status}}",
  accent = "{{accent}}",
}) {
  const statusStyle = {
    "Backlog": { color: "#5b5266", borderColor: "#5b5266", background: "#24143010" },
    "In progress": { color: "#1a3a5c", borderColor: "#6ea3d6", background: "#BFD9F250" },
    "Done": { color: "#1c5c34", borderColor: "#5fae7f", background: "#A8E6C150" },
  }[status] ?? {};
  return (
    <article style={{ fontFamily: "system-ui, sans-serif", maxWidth: 420, padding: "18px 20px",
      background: "#FAF7F2", color: "#241430", borderRadius: 10, boxShadow: "0 6px 18px rgba(36,20,48,.12)",
      borderTop: "4px solid " + accent }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
        <span style={{ fontWeight: 700, fontSize: 13, background: "#24143014", padding: "3px 9px", borderRadius: 999 }}>{points} pts</span>
        <span style={{ fontWeight: 600, fontSize: 12, padding: "3px 10px", borderRadius: 999, border: "1.5px solid", ...statusStyle }}>{status}</span>
      </div>
      <p style={{ margin: 0, lineHeight: 1.6, fontSize: 14 }}>
        <strong>As a</strong> {persona}, <strong>I want</strong> {need}, <strong>so that</strong> {benefit}.
      </p>
    </article>
  );
}
